import * as THREE from "three";

// Late-afternoon light, sun low behind the wave so the lip glows.
export const SUN_DIR = new THREE.Vector3(-0.75, 0.36, -0.62).normalize();

export const palette = {
  zenith: new THREE.Color("#2a5fa8"),
  horizon: new THREE.Color("#f6d2a6"),
  sun: new THREE.Color("#fff1d8"),
};

export const skyUniforms = {
  uSunDir: { value: SUN_DIR },
  uZenith: { value: palette.zenith },
  uHorizon: { value: palette.horizon },
  uSunColor: { value: palette.sun },
};

// Shared between the sky dome and the water reflections / horizon haze.
export const skyGLSL = /* glsl */ `
uniform vec3 uSunDir;
uniform vec3 uZenith;
uniform vec3 uHorizon;
uniform vec3 uSunColor;

vec3 skyColor(vec3 d) {
  float y = clamp(d.y, 0.0, 1.0);
  vec3 col = mix(uHorizon, uZenith, pow(y, 0.42));
  // slight blue band just above the horizon away from the sun
  float sd = max(dot(d, uSunDir), 0.0);
  col = mix(col, uHorizon * vec3(1.05, 0.92, 0.85), (1.0 - smoothstep(0.0, 0.25, y)) * 0.35 * sd);
  col += uSunColor * (pow(sd, 5.0) * 0.28 + pow(sd, 48.0) * 0.55);
  return col;
}
`;

export function createSky() {
  const group = new THREE.Group();

  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(1500, 48, 24),
    new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: { ...skyUniforms },
      vertexShader: /* glsl */ `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }`,
      fragmentShader: /* glsl */ `
        varying vec3 vDir;
        ${skyGLSL}
        void main() {
          vec3 d = normalize(vDir);
          vec3 col = skyColor(d);
          float sd = dot(d, uSunDir);
          col += uSunColor * smoothstep(0.99955, 0.99975, sd) * 30.0;
          gl_FragColor = vec4(col, 1.0);
        }`,
    })
  );
  dome.renderOrder = -10;
  dome.frustumCulled = false;
  group.add(dome);

  // Distant islands: hazy silhouettes on the horizon.
  const haze = palette.horizon.clone().lerp(new THREE.Color("#5a6f8a"), 0.42);
  const islandMat = new THREE.MeshBasicMaterial({ color: haze });
  const islands = [
    [-0.95, 1.0, 70, 26],
    [-0.82, 1.05, 110, 44],
    [-0.7, 1.0, 50, 18],
    [-0.35, 0.98, 40, 12],
    [0.55, 1.0, 90, 20],
  ];
  for (const [ang, dist, w, h] of islands) {
    const m = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 12, 0, Math.PI * 2, 0, Math.PI / 2), islandMat);
    const r = 1100 * dist;
    m.position.set(Math.sin(ang) * r, -2, -Math.cos(ang) * r);
    m.scale.set(w, h, w * 0.6);
    m.rotation.y = -ang;
    m.renderOrder = -9;
    group.add(m);
  }

  // Painted clouds, generated on a canvas.
  const cloudTex = makeCloudTexture();
  const rand = mulberry(7);
  for (let i = 0; i < 16; i++) {
    const ang = -1.9 + rand() * 3.4;
    const elev = 0.03 + rand() * 0.2;
    const r = 1150;
    const mat = new THREE.SpriteMaterial({
      map: cloudTex,
      transparent: true,
      depthWrite: false,
      fog: false,
      opacity: 0.55 + rand() * 0.35,
    });
    // clouds near the sun are warmer
    const toSun = Math.max(0, Math.cos(ang - Math.atan2(SUN_DIR.x, -SUN_DIR.z)));
    mat.color.set("#ffffff").lerp(new THREE.Color("#ffc9a0"), toSun * 0.6);
    const s = new THREE.Sprite(mat);
    s.position.set(Math.sin(ang) * r * Math.cos(elev), Math.sin(elev) * r + 20, -Math.cos(ang) * r * Math.cos(elev));
    const w = 160 + rand() * 260;
    s.scale.set(w, w * (0.28 + rand() * 0.12), 1);
    s.renderOrder = -8;
    group.add(s);
  }

  return {
    group,
    update(camera) {
      group.position.copy(camera.position);
    },
  };
}

function makeCloudTexture() {
  const c = document.createElement("canvas");
  c.width = 512;
  c.height = 192;
  const g = c.getContext("2d");
  const rand = mulberry(3);
  for (let i = 0; i < 70; i++) {
    const x = 70 + rand() * 372;
    const bulge = Math.sin(((x - 70) / 372) * Math.PI);
    const y = 120 - rand() * 60 * bulge;
    const r = 18 + rand() * 40 * (0.4 + bulge);
    const grd = g.createRadialGradient(x, y, 0, x, y, r);
    const shade = Math.round(235 + (y < 100 ? 20 : 0));
    grd.addColorStop(0, `rgba(${shade},${shade},${shade},0.55)`);
    grd.addColorStop(1, `rgba(${shade},${shade},${shade},0)`);
    g.fillStyle = grd;
    g.beginPath();
    g.arc(x, y, r, 0, Math.PI * 2);
    g.fill();
  }
  // soft flat underside
  const fade = g.createLinearGradient(0, 120, 0, 192);
  fade.addColorStop(0, "rgba(0,0,0,0)");
  fade.addColorStop(1, "rgba(0,0,0,1)");
  g.globalCompositeOperation = "destination-out";
  g.fillStyle = fade;
  g.fillRect(0, 120, 512, 72);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function mulberry(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

import * as THREE from "three";
import { skyGLSL, skyUniforms } from "./sky.js";

// Everything is simulated in a frame that rides along with the surfer:
// the wave crest sits on the x axis (z = 0) and breaks toward +z.
// The open water slides past at (VX, VZ) to sell the motion.
export const VX = 4.2; // surfer speed along the wave
export const VZ = 7.0; // wave travel speed
const NOISE_PERIOD = 289 / 0.05; // simplex noise repeats every 289 lattice units
const AMP_PERIOD = (Math.PI * 2) / 0.05;
export const TRAIL_COUNT = 56;

// small travelling swells: [dirX, dirZ, wavelength, amplitude]
const SMALL = [
  [0.0, 1.0, 9.0, 0.11],
  [0.3, 0.95, 5.6, 0.07],
  [-0.5, 0.86, 3.8, 0.05],
  [0.8, 0.6, 2.4, 0.03],
  [-0.9, 0.42, 1.7, 0.02],
];
const waves = SMALL.map(([dx, dz, L, a]) => {
  const l = Math.hypot(dx, dz);
  const k = (Math.PI * 2) / L;
  return { dx: dx / l, dz: dz / l, k, a, w: Math.sqrt(9.8 * k) };
});

const state = { offS: 0, phases: new Float32Array(waves.length) };

export function heroProfile(z) {
  const w = z > 0 ? 4.0 : 11.0;
  return Math.exp((-z * z) / (w * w));
}
export function brokenAmt(x) {
  return 1 - smoothstep(-17, -7, x);
}
function heroAmp(x) {
  const s = x + state.offS;
  const a = 3.7 + 0.3 * Math.sin(s * 0.05) + 0.2 * Math.sin(s * 0.15 + 1.3);
  return a * (1 - 0.5 * brokenAmt(x));
}
function swells(x, z) {
  return (
    heroAmp(x) * heroProfile(z) +
    1.8 * Math.exp(-(((z + 38) / 12) ** 2)) * (1 + 0.2 * Math.sin((x + state.offS) * 0.05 + 2.0)) +
    1.2 * Math.exp(-(((z + 75) / 14) ** 2))
  );
}
function smallWaves(x, z) {
  let h = 0;
  for (let i = 0; i < waves.length; i++) {
    const w = waves[i];
    h += w.a * Math.sin(w.k * (w.dx * x + w.dz * z) + state.phases[i]);
  }
  return h;
}

// Water height at frame coordinates (ignores the lip push, which only
// matters above where the board ever goes).
export function heightAt(x, z) {
  return swells(x, z) + smallWaves(x, z) * (1 - 0.6 * heroProfile(z));
}

export function normalAt(x, z, out = new THREE.Vector3()) {
  const e = 0.12;
  const hx = heightAt(x + e, z) - heightAt(x - e, z);
  const hz = heightAt(x, z + e) - heightAt(x, z - e);
  return out.set(-hx, 2 * e, -hz).normalize();
}

function smoothstep(a, b, x) {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

const noiseGLSL = /* glsl */ `
vec3 permute3(vec3 x) { return mod(((x * 34.0) + 1.0) * x, 289.0); }
float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);
  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = permute3(permute3(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m; m = m * m;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}
`;

const commonGLSL = /* glsl */ `
uniform float uTime;
uniform vec2 uOffN;
uniform float uOffS;
uniform vec4 uWaves[5];
uniform float uPhase[5];

float heroProfile(float z) { float w = z > 0.0 ? 4.0 : 11.0; return exp(-z * z / (w * w)); }
float brokenAmt(float x) { return 1.0 - smoothstep(-17.0, -7.0, x); }
float heroAmp(float x) {
  float s = x + uOffS;
  float a = 3.7 + 0.3 * sin(s * 0.05) + 0.2 * sin(s * 0.15 + 1.3);
  return a * (1.0 - 0.5 * brokenAmt(x));
}
float swells(vec2 p) {
  return heroAmp(p.x) * heroProfile(p.y)
    + 1.8 * exp(-pow((p.y + 38.0) / 12.0, 2.0)) * (1.0 + 0.2 * sin((p.x + uOffS) * 0.05 + 2.0))
    + 1.2 * exp(-pow((p.y + 75.0) / 14.0, 2.0));
}
float smallWaves(vec2 p) {
  float h = 0.0;
  for (int i = 0; i < 5; i++) h += uWaves[i].w * sin(uWaves[i].z * dot(uWaves[i].xy, p) + uPhase[i]);
  return h;
}
`;

const vertexShader = /* glsl */ `
${noiseGLSL}
${commonGLSL}
varying vec3 vWorld;
varying vec3 vNormal;
varying vec2 vFrame;
varying float vProf;

vec3 displace(vec2 p) {
  float prof = heroProfile(p.y);
  float broken = brokenAmt(p.x);
  float h = swells(p) + smallWaves(p) * (1.0 - 0.6 * prof);
  // churning whitewater on the broken section
  vec2 q = p + uOffN;
  float churn = snoise(q * 0.4 + vec2(0.0, uTime * 0.35)) * 0.5 + snoise(q * 0.8 - vec2(uTime * 0.5, 0.0)) * 0.25;
  float wwMask = broken * smoothstep(-3.0, 1.0, p.y) * (1.0 - smoothstep(10.0, 30.0, p.y));
  h += churn * 0.45 * wwMask;
  // the lip pitches forward on the unbroken section
  float lip = pow(prof, 8.0) * (1.0 - broken);
  float dz = 2.1 * lip;
  h += 0.25 * lip;
  // the broken section's crest rolls forward as a soft foam wall
  dz += 1.2 * pow(prof, 4.0) * broken;
  return vec3(p.x, h, p.y + dz);
}

void main() {
  vec2 p = position.xz;
  vec3 P = displace(p);
  float e = 0.12;
  vec3 Px = displace(p + vec2(e, 0.0));
  vec3 Pz = displace(p + vec2(0.0, e));
  vNormal = normalize(cross(Pz - P, Px - P));
  vFrame = p;
  vProf = heroProfile(p.y);
  vec4 world = modelMatrix * vec4(P, 1.0);
  vWorld = world.xyz;
  gl_Position = projectionMatrix * viewMatrix * world;
}
`;

const fragmentShader = /* glsl */ `
${noiseGLSL}
${commonGLSL}
${skyGLSL}
uniform vec3 uDeep;
uniform vec3 uFace;
uniform vec3 uGlow;
uniform vec4 uTrail[${TRAIL_COUNT}];
uniform vec3 uBoard;

varying vec3 vWorld;
varying vec3 vNormal;
varying vec2 vFrame;
varying float vProf;

float fbm(vec2 p) {
  float f = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++) { f += a * snoise(p); p *= 2.0; a *= 0.5; }
  return f;
}

vec2 rippleGrad(vec2 q, float t) {
  vec2 g = vec2(0.0);
  // [dirAngle, k, amp]
  vec3 R[6];
  R[0] = vec3(0.3, 2.1, 0.030);
  R[1] = vec3(-0.7, 3.3, 0.020);
  R[2] = vec3(1.4, 4.7, 0.014);
  R[3] = vec3(-1.9, 6.9, 0.009);
  R[4] = vec3(2.6, 9.3, 0.006);
  R[5] = vec3(0.9, 13.0, 0.004);
  for (int i = 0; i < 6; i++) {
    vec2 d = vec2(sin(R[i].x), cos(R[i].x));
    float w = sqrt(9.8 * R[i].y);
    float c = cos(R[i].y * dot(d, q) - w * t);
    g += d * (R[i].y * R[i].z * c);
  }
  return g;
}

void main() {
  vec3 N = normalize(vNormal);
  if (!gl_FrontFacing) N = -N;
  vec3 toCam = cameraPosition - vWorld;
  float dist = length(toCam);
  vec3 V = toCam / dist;

  vec2 q = vFrame + uOffN;
  float broken = brokenAmt(vFrame.x);

  // fine ripples (fade out with distance to avoid shimmer)
  vec2 rg = rippleGrad(q, uTime) * exp(-dist * 0.025);
  N = normalize(N + vec3(-rg.x, 0.0, -rg.y));

  float NdV = max(dot(N, V), 0.0);
  float fres = 0.02 + 0.98 * pow(1.0 - NdV, 5.0);
  vec3 R = reflect(-V, N);
  R.y = abs(R.y);
  vec3 refl = skyColor(R);

  // body colour: deep blue on the flats, turquoise up the face
  float face = smoothstep(0.05, 0.7, vProf) * (vFrame.y > -6.0 ? 1.0 : 0.4);
  vec3 body = mix(uDeep, uFace, face);
  float NdL = max(dot(N, uSunDir), 0.0);
  body *= 0.55 + 0.45 * NdL;

  // light shining through the thin lip
  float thin = smoothstep(0.45, 0.98, vProf) * (1.0 - broken * 0.7);
  float back = pow(clamp(dot(-V, uSunDir) * 0.5 + 0.5, 0.0, 1.0), 3.0);
  vec3 sss = uGlow * thin * (0.35 + 1.6 * back);
  body += sss * (0.6 + 0.4 * (1.0 - NdV));

  vec3 col = mix(body, refl, fres);

  // sun glints
  float sp = max(dot(R, uSunDir), 0.0);
  col += uSunColor * (pow(sp, 600.0) * 14.0 + pow(sp, 80.0) * 0.5) * (0.4 + 0.6 * fres);

  // ---- foam ----
  float n1 = fbm(q * 0.4 + vec2(0.0, uTime * 0.05));
  float n2 = fbm(q * vec2(0.8, 1.6) - vec2(uTime * 0.1, 0.0));
  // feathering lip
  float lipFoam = smoothstep(0.86, 0.985, vProf) * smoothstep(-2.0, 0.5, vFrame.y);
  lipFoam *= smoothstep(-0.15, 0.35, n2 + 0.25);
  // whitewater on the broken section and the foam it leaves on the flats
  float ww = broken * smoothstep(-6.0, 0.0, vFrame.y) * (1.0 - smoothstep(8.0, 34.0, vFrame.y));
  float wwFoam = ww * smoothstep(-0.25, 0.25, n1 + 0.45 - 0.5 * smoothstep(4.0, 30.0, vFrame.y));
  // old foam streaks drifting on the flats and over the back
  float streak = smoothstep(0.42, 0.62, fbm(q * vec2(0.12, 0.35) * 2.0) + 0.15 * n2) * 0.55;
  streak *= 1.0 - smoothstep(0.2, 0.7, vProf) * step(0.0, vFrame.y);
  // board trail
  float trail = 0.0;
  for (int i = 0; i < ${TRAIL_COUNT}; i++) {
    vec4 t = uTrail[i];
    vec2 d = vFrame - t.xy;
    trail += t.z * exp(-dot(d, d) * t.w);
  }
  trail = clamp(trail, 0.0, 1.0) * smoothstep(-0.2, 0.4, n2 + trail * 0.6);
  float foam = max(max(lipFoam, wwFoam), max(streak, trail));

  vec3 foamCol = vec3(0.92, 0.95, 0.97) * (0.62 + 0.38 * NdL) + uGlow * thin * back * 1.4;
  foamCol += uSunColor * 0.12;
  col = mix(col, foamCol, clamp(foam, 0.0, 1.0));

  // contact shadow under the board
  vec2 bd = vFrame - uBoard.xz;
  col *= 1.0 - 0.35 * exp(-dot(bd, bd) * 1.3);

  // aerial haze toward the horizon
  vec3 hz = normalize(vec3(-V.x, max(-V.y, 0.0) * 0.3, -V.z));
  float fogF = 1.0 - exp(-max(dist - 30.0, 0.0) * 0.0032);
  col = mix(col, skyColor(hz), fogF);

  gl_FragColor = vec4(col, 1.0);
}
`;

function warpedGrid(size, segs) {
  // dense near the surfer, coarse toward the horizon
  const coord = (u) => size * Math.sign(u) * (0.08 * Math.abs(u) + 0.92 * Math.pow(Math.abs(u), 4));
  const pos = new Float32Array((segs + 1) * (segs + 1) * 3);
  let k = 0;
  for (let j = 0; j <= segs; j++) {
    const z = coord((j / segs) * 2 - 1);
    for (let i = 0; i <= segs; i++) {
      const x = coord((i / segs) * 2 - 1);
      pos[k++] = x;
      pos[k++] = 0;
      pos[k++] = z;
    }
  }
  const idx = [];
  for (let j = 0; j < segs; j++) {
    for (let i = 0; i < segs; i++) {
      const a = j * (segs + 1) + i;
      const b = a + 1;
      const c = a + segs + 1;
      const d = c + 1;
      idx.push(a, c, b, b, c, d);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setIndex(idx);
  return g;
}

export function createOcean() {
  const trail = [];
  for (let i = 0; i < TRAIL_COUNT; i++) trail.push(new THREE.Vector4(0, 0, 0, 1));
  const uniforms = {
    ...skyUniforms,
    uTime: { value: 0 },
    uOffN: { value: new THREE.Vector2() },
    uOffS: { value: 0 },
    uWaves: { value: waves.map((w) => new THREE.Vector4(w.dx, w.dz, w.k, w.a)) },
    uPhase: { value: Array.from(state.phases) },
    uDeep: { value: new THREE.Color("#06304a") },
    uFace: { value: new THREE.Color("#0f6a78") },
    uGlow: { value: new THREE.Color("#35d6be") },
    uTrail: { value: trail },
    uBoard: { value: new THREE.Vector3() },
  };
  const mesh = new THREE.Mesh(
    warpedGrid(1300, 420),
    new THREE.ShaderMaterial({ uniforms, vertexShader, fragmentShader, side: THREE.DoubleSide })
  );
  mesh.frustumCulled = false;

  return {
    mesh,
    uniforms,
    trail,
    update(t) {
      // offsets are accumulated in double precision on the CPU and wrapped
      // at the period of whatever consumes them
      const ox = VX * t;
      const oz = VZ * t;
      state.offS = ox % AMP_PERIOD;
      for (let i = 0; i < waves.length; i++) {
        const w = waves[i];
        state.phases[i] = (w.k * (w.dx * ox + w.dz * oz) - w.w * t) % (Math.PI * 2);
        uniforms.uPhase.value[i] = state.phases[i];
      }
      uniforms.uTime.value = t;
      uniforms.uOffS.value = state.offS;
      uniforms.uOffN.value.set(ox % NOISE_PERIOD, oz % NOISE_PERIOD);
    },
  };
}

import * as THREE from "three";
import { loft, v3 } from "./loft.js";

export const BOARD_LENGTH = 2.3;

// Half-width of the outline at u in [0,1] (tail -> nose).
function halfWidth(u) {
  const e = Math.max(0, 1 - ((u - 0.45) / 0.55) ** 2);
  const tailRound = Math.min(1, u / 0.03) ** 0.5;
  return 0.29 * Math.pow(e, 0.36) * tailRound + 0.002;
}
function rocker(x) {
  const n = Math.max(0, (x - 0.35) / 0.8);
  const t = Math.max(0, (-x - 0.7) / 0.45);
  return 0.13 * n * n + 0.035 * t * t;
}

export function createBoard() {
  const group = new THREE.Group();
  const L = BOARD_LENGTH;
  const pts = [];
  for (let i = 0; i <= 24; i++) {
    const x = -L / 2 + (i / 24) * L;
    pts.push(v3(x, rocker(x), 0));
  }
  const deck = new THREE.Color("#fbf3e4");
  const bottom = new THREE.Color("#e9dccb");
  const stripe = new THREE.Color("#e2492f");
  const stripe2 = new THREE.Color("#2b8fb3");
  const rail = new THREE.Color("#f2b134");
  const geo = loft(
    pts,
    (t) => {
      const w = halfWidth(t);
      const thick = 0.045 * Math.pow(Math.sin(Math.PI * Math.min(1, t * 0.97 + 0.02)), 0.4) + 0.006;
      return [w, thick];
    },
    {
      segments: 90,
      radial: 28,
      power: 0.55,
      color: (t, off, c) => {
        const up = off.y;
        const side = Math.abs(off.z);
        const w = halfWidth(t);
        if (up < -0.004) return c.copy(bottom);
        if (side > w * 0.86) return c.copy(rail);
        // centre stripe plus a band near the nose
        if (side < 0.03 && t > 0.08 && t < 0.84) return c.copy(stripe);
        if (side < 0.052 && side > 0.04 && t > 0.08 && t < 0.84) return c.copy(stripe2);
        if (t > 0.86 && t < 0.885) return c.copy(stripe);
        return c.copy(deck);
      },
    }
  );
  // the loft path is centred in the board; lift so the deck sits at y≈0
  geo.translate(0, -0.045, 0);
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.35, metalness: 0.0 });
  const board = new THREE.Mesh(geo, mat);
  board.castShadow = true;
  board.receiveShadow = true;
  group.add(board);

  // single fin
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.quadraticCurveTo(-0.02, -0.12, -0.13, -0.2);
  finShape.quadraticCurveTo(-0.08, -0.08, -0.16, 0);
  finShape.lineTo(0, 0);
  const finGeo = new THREE.ExtrudeGeometry(finShape, {
    depth: 0.012,
    bevelEnabled: true,
    bevelThickness: 0.004,
    bevelSize: 0.004,
    bevelSegments: 2,
    curveSegments: 10,
  });
  finGeo.translate(0, 0, -0.006);
  const fin = new THREE.Mesh(finGeo, new THREE.MeshStandardMaterial({ color: "#2b8fb3", roughness: 0.3 }));
  fin.position.set(-L / 2 + 0.28, -0.075, 0);
  fin.castShadow = true;
  group.add(fin);

  return { group, deckHeight: (x) => rocker(x) - 0.004 };
}

import * as THREE from "three";
import { loft, v3 } from "./loft.js";

// A brown pelican in breeding plumage, built from lofted primitives.
// Local frame: forward +X, up +Y, left +Z. Origin is on the deck between the feet.

const C = {
  back: new THREE.Color("#8f877c"),
  backStreak: new THREE.Color("#5e554c"),
  belly: new THREE.Color("#4b3a2f"),
  white: new THREE.Color("#f4efe4"),
  crown: new THREE.Color("#f3d77a"),
  chestnut: new THREE.Color("#5a2e1f"),
  covert: new THREE.Color("#bdb6aa"),
  covertDark: new THREE.Color("#7c7368"),
  flight: new THREE.Color("#2e2520"),
  underwing: new THREE.Color("#4f463f"),
  bill: new THREE.Color("#c9b9a6"),
  billTip: new THREE.Color("#e8692e"),
  pouch: new THREE.Color("#7b3a2f"),
  leg: new THREE.Color("#2f3033"),
};

const feather = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85 });
const glossy = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.45 });
const legMat = new THREE.MeshStandardMaterial({ color: C.leg, roughness: 0.7 });

function mesh(geo, mat = feather) {
  const m = new THREE.Mesh(geo, mat);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function featherGeo(length, width, color) {
  return loft(
    [v3(0, 0, 0), v3(length * 0.5, 0, 0.004), v3(length, 0, 0)],
    (t) => [width * Math.pow(Math.sin(Math.PI * Math.min(1, 0.08 + t * 0.92)), 0.6) * (1 - 0.35 * t), 0.006],
    { segments: 10, radial: 8, color: (t, off, c) => c.copy(color).multiplyScalar(off.y < 0 ? 0.8 : 1) }
  );
}

function buildWing(side) {
  const s = side; // +1 left, -1 right
  const shoulder = new THREE.Group();
  shoulder.rotation.order = "YXZ";

  const inner = mesh(
    loft(
      [v3(-0.05, 0, 0), v3(-0.06, 0.012, 0.24 * s), v3(-0.085, 0, 0.47 * s)],
      (t) => [0.135 - 0.03 * t, 0.034 - 0.018 * t],
      {
        segments: 20,
        radial: 16,
        color: (t, off, c) => {
          if (off.y < -0.002) return c.copy(C.underwing);
          if (off.x > -0.02) {
            // streaky silver coverts on the leading half
            const k = 0.5 + 0.5 * Math.sin(t * 60 + off.x * 90);
            return c.copy(C.covert).lerp(C.covertDark, k * 0.45 + (off.x > 0.08 ? 0.2 : 0));
          }
          return c.copy(C.flight);
        },
      }
    )
  );
  shoulder.add(inner);

  const wrist = new THREE.Group();
  wrist.rotation.order = "YXZ";
  wrist.position.set(-0.07, 0, 0.47 * s);
  shoulder.add(wrist);

  const hand = mesh(
    loft(
      [v3(0, 0, 0), v3(-0.02, 0, 0.13 * s), v3(-0.05, 0, 0.24 * s)],
      (t) => [0.115 - 0.05 * t, 0.018 - 0.008 * t],
      {
        segments: 12,
        radial: 14,
        color: (t, off, c) =>
          off.y < -0.002 ? c.copy(C.underwing) : off.x > 0.02 ? c.copy(C.covertDark) : c.copy(C.flight),
      }
    )
  );
  wrist.add(hand);

  // primaries fan from the tip of the hand
  const primaries = [];
  for (let i = 0; i < 7; i++) {
    const len = 0.27 + 0.05 * Math.sin((i / 6) * Math.PI) - i * 0.01;
    const f = mesh(featherGeo(len, 0.03, C.flight));
    const pivot = new THREE.Group();
    pivot.position.set(-0.03 - i * 0.022, 0, (0.2 + 0.01 * i) * s);
    const baseAng = 0.15 - i * 0.16;
    // feather geometry points along +X; turn it to point outward along the span
    pivot.rotation.y = -s * (Math.PI / 2) + s * baseAng;
    pivot.add(f);
    wrist.add(pivot);
    primaries.push({ pivot, baseAng });
  }

  return { shoulder, wrist, primaries, side: s };
}

function buildLegMesh(rTop, rBot) {
  const g = new THREE.CylinderGeometry(rBot, rTop, 1, 10, 1);
  g.translate(0, 0.5, 0); // spans y 0..1, bottom at origin
  return g;
}

function buildFoot(side) {
  const sh = new THREE.Shape();
  sh.moveTo(-0.025, 0);
  const tips = [
    [0.1, 0.07],
    [0.14, 0.012],
    [0.11, -0.055],
  ];
  sh.lineTo(tips[0][0], tips[0][1]);
  sh.quadraticCurveTo(0.08, 0.035, tips[1][0], tips[1][1]);
  sh.quadraticCurveTo(0.08, -0.015, tips[2][0], tips[2][1]);
  sh.lineTo(-0.025, -0.012);
  sh.lineTo(-0.025, 0);
  const g = new THREE.ExtrudeGeometry(sh, { depth: 0.012, bevelEnabled: true, bevelSize: 0.006, bevelThickness: 0.004, bevelSegments: 2 });
  g.rotateX(-Math.PI / 2);
  if (side < 0) g.scale(1, 1, -1);
  const m = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ color: C.leg, roughness: 0.7, side: THREE.DoubleSide }));
  m.castShadow = true;
  return m;
}

export function createPelican() {
  const root = new THREE.Group();
  const hips = new THREE.Group();
  hips.rotation.order = "YXZ";
  hips.position.set(-0.04, 0.42, 0);
  root.add(hips);

  // ---- body ----
  const body = mesh(
    loft(
      [v3(-0.46, -0.03, 0), v3(-0.3, 0.02, 0), v3(-0.06, 0.12, 0), v3(0.14, 0.26, 0), v3(0.22, 0.38, 0)],
      (t) => {
        const f = Math.pow(Math.sin(Math.PI * Math.min(1, Math.pow(t, 0.85) * 0.97 + 0.02)), 0.55);
        return [0.21 * f, 0.19 * f];
      },
      {
        segments: 40,
        radial: 22,
        color: (t, off, c) => {
          if (off.y < -0.03 || (t > 0.75 && off.x > 0.05)) return c.copy(C.belly);
          const k = 0.5 + 0.5 * Math.sin(t * 70 + off.z * 40);
          return c.copy(C.back).lerp(C.backStreak, k * 0.5);
        },
      }
    )
  );
  hips.add(body);

  // tail fan
  for (let i = 0; i < 5; i++) {
    const f = mesh(featherGeo(0.17, 0.035, C.flight));
    f.position.set(-0.4, -0.02, (i - 2) * 0.025);
    f.rotation.set(0, Math.PI + (i - 2) * 0.22, 0.35);
    hips.add(f);
  }

  // ---- neck ----
  const neckPts = [v3(0.12, 0.27, 0), v3(0.2, 0.46, 0), v3(0.13, 0.6, 0), v3(0.16, 0.73, 0), v3(0.25, 0.8, 0)];
  const neck = mesh(
    loft(neckPts, (t) => [0.085 - 0.03 * t, 0.088 - 0.03 * t], {
      segments: 30,
      radial: 18,
      up: v3(1, 0, 0),
      color: (t, off, c) => {
        // dark chestnut hind-neck, white front and sides
        const back = -off.x / (Math.hypot(off.x, off.z) + 1e-5);
        if (back > 0.55 && t > 0.12 && t < 0.95) return c.copy(C.chestnut);
        if (t < 0.1) return c.copy(C.back).lerp(C.white, t * 10);
        return c.copy(C.white);
      },
    })
  );
  hips.add(neck);

  // ---- head ----
  const head = new THREE.Group();
  head.rotation.order = "YXZ";
  head.position.set(0.26, 0.81, 0);
  hips.add(head);

  const skull = mesh(new THREE.SphereGeometry(1, 24, 16), new THREE.MeshStandardMaterial({ color: C.white, roughness: 0.8 }));
  skull.scale.set(0.095, 0.072, 0.064);
  skull.position.set(0.03, 0.005, 0);
  head.add(skull);
  const crown = mesh(new THREE.SphereGeometry(1, 20, 12), new THREE.MeshStandardMaterial({ color: C.crown, roughness: 0.8 }));
  crown.scale.set(0.07, 0.035, 0.05);
  crown.position.set(0.04, 0.05, 0);
  head.add(crown);

  const eyes = [];
  for (const s of [1, -1]) {
    const eye = new THREE.Group();
    eye.position.set(0.075, 0.018, 0.05 * s);
    const ring = mesh(new THREE.SphereGeometry(0.02, 16, 12), new THREE.MeshStandardMaterial({ color: "#e7a7a0", roughness: 0.6 }));
    ring.scale.set(1, 1, 0.5);
    eye.add(ring);
    const ball = mesh(new THREE.SphereGeometry(0.015, 16, 12), new THREE.MeshStandardMaterial({ color: "#f6f1d6", roughness: 0.2 }));
    ball.position.z = 0.006 * s;
    eye.add(ball);
    const pupil = mesh(new THREE.SphereGeometry(0.0085, 12, 10), new THREE.MeshStandardMaterial({ color: "#0d0b0a", roughness: 0.1 }));
    pupil.position.set(0.004, 0.001, 0.0145 * s);
    eye.add(pupil);
    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.0028, 8, 6), new THREE.MeshBasicMaterial({ color: "#ffffff" }));
    glint.position.set(0.008, 0.006, 0.02 * s);
    eye.add(glint);
    head.add(eye);
    eyes.push(eye);
  }

  // upper mandible with an orange hooked tip
  const billPts = [v3(0.08, 0.0, 0), v3(0.3, -0.04, 0), v3(0.52, -0.09, 0), v3(0.6, -0.11, 0), v3(0.635, -0.125, 0), v3(0.64, -0.15, 0)];
  const upper = mesh(
    loft(
      billPts,
      (t) => [0.04 - 0.02 * t, t > 0.9 ? 0.016 - (t - 0.9) * 0.1 : 0.017],
      {
        segments: 40,
        radial: 14,
        power: 0.8,
        color: (t, off, c) => {
          if (t > 0.88) return c.copy(C.billTip);
          const k = Math.max(0, (t - 0.55) / 0.33);
          return c.copy(C.bill).lerp(C.billTip, k * k * 0.6);
        },
      }
    ),
    glossy
  );
  head.add(upper);

  // lower mandible + sagging gular pouch, hinged so the bill can open
  const jaw = new THREE.Group();
  jaw.position.set(0.07, -0.02, 0);
  head.add(jaw);
  const pouchGeo = loft(
    [v3(0.0, -0.01, 0), v3(0.14, -0.06, 0), v3(0.3, -0.09, 0), v3(0.46, -0.1, 0), v3(0.56, -0.105, 0)],
    (t) => [0.034 - 0.012 * t, 0.012 + 0.032 * Math.pow(Math.sin(Math.PI * Math.min(1, t * 1.1)), 1.3)],
    {
      segments: 30,
      radial: 16,
      color: (t, off, c) => (off.y > 0.006 ? c.copy(C.bill).multiplyScalar(0.85) : c.copy(C.pouch).lerp(C.chestnut, 0.3 * (1 - t))),
    }
  );
  const pouch = mesh(pouchGeo, glossy);
  jaw.add(pouch);

  // ---- wings ----
  const wings = [buildWing(1), buildWing(-1)];
  for (const w of wings) {
    w.shoulder.position.set(0.06, 0.25, 0.13 * w.side);
    hips.add(w.shoulder);
  }

  // ---- legs (posed with two-bone IK every frame) ----
  const legs = [1, -1].map((s) => {
    const upperLeg = mesh(buildLegMesh(0.042, 0.022), new THREE.MeshStandardMaterial({ color: C.belly, roughness: 0.9 }));
    const lowerLeg = mesh(buildLegMesh(0.02, 0.016), legMat);
    const knee = mesh(new THREE.SphereGeometry(0.022, 10, 8), legMat);
    const foot = buildFoot(s);
    const footPos = v3(s > 0 ? 0.03 : -0.05, 0.004, 0.13 * s);
    foot.position.copy(footPos).add(v3(-0.015, 0, 0));
    foot.rotation.y = s * 0.15;
    root.add(upperLeg, lowerLeg, knee, foot);
    return { upperLeg, lowerLeg, knee, foot, footPos, hipLocal: v3(-0.02, -0.02, 0.085 * s), side: s };
  });

  const anim = {
    blinkT: 2,
    flap: 0,
    flapT: 5,
    clap: 0,
    clapT: 9,
    lookT: 6,
    look: 0,
    lookTarget: 0,
  };

  const tmpA = new THREE.Vector3();
  const tmpB = new THREE.Vector3();
  const tmpC = new THREE.Vector3();
  const Y = new THREE.Vector3(0, 1, 0);

  function placeBone(m, from, to) {
    tmpC.subVectors(to, from);
    const len = tmpC.length();
    m.position.copy(from);
    m.quaternion.setFromUnitVectors(Y, tmpC.divideScalar(len));
    m.scale.set(1, len, 1);
  }

  function solveLegs() {
    hips.updateMatrix();
    const L1 = 0.25;
    const L2 = 0.23;
    for (const leg of legs) {
      const H = tmpA.copy(leg.hipLocal).applyMatrix4(hips.matrix);
      const F = leg.footPos;
      const dir = tmpB.subVectors(F, H);
      let d = dir.length();
      dir.divideScalar(d);
      d = Math.min(d, L1 + L2 - 0.001);
      const a = (L1 * L1 - L2 * L2 + d * d) / (2 * d);
      const h = Math.sqrt(Math.max(0, L1 * L1 - a * a));
      // the ankle points backward, like a real bird
      const hint = new THREE.Vector3(-1, 0, 0.15 * leg.side);
      hint.addScaledVector(dir, -hint.dot(dir)).normalize();
      const K = H.clone().addScaledVector(dir, a).addScaledVector(hint, h);
      const Fc = H.clone().addScaledVector(dir, d);
      placeBone(leg.upperLeg, K, H);
      placeBone(leg.lowerLeg, Fc, K);
      leg.knee.position.copy(K);
    }
  }

  // ctx: { lean, compress, camLocal (Vector3 in root space), dt, t }
  function update(ctx) {
    const { t, dt, lean, compress } = ctx;

    // posture: crouch into compression, bank with the board
    hips.position.y = 0.43 - compress * 0.07 + Math.sin(t * 2.3) * 0.008;
    hips.position.x = -0.04 - compress * 0.02;
    hips.rotation.z = -0.12 - compress * 0.12 + Math.sin(t * 1.1) * 0.02;
    hips.rotation.x = lean * 0.22 + Math.sin(t * 0.9) * 0.02;
    hips.rotation.y = -lean * 0.08;

    // head stays level and occasionally glances at the camera
    anim.lookT -= dt;
    if (anim.lookT < 0) {
      if (anim.lookTarget === 0) {
        const c = ctx.camLocal;
        anim.lookTarget = THREE.MathUtils.clamp(Math.atan2(-c.z, c.x), -1.1, 1.1);
        anim.lookT = 1.6 + Math.random() * 1.2;
      } else {
        anim.lookTarget = 0;
        anim.lookT = 4 + Math.random() * 5;
      }
    }
    anim.look += (anim.lookTarget - anim.look) * Math.min(1, dt * 5);
    head.rotation.y = anim.look - hips.rotation.y + Math.sin(t * 1.7) * 0.04;
    head.rotation.x = -hips.rotation.x * 0.9;
    head.rotation.z = -hips.rotation.z * 0.85 - 0.1 + Math.sin(t * 2.9) * 0.03;

    // blink
    anim.blinkT -= dt;
    let lid = 1;
    if (anim.blinkT < 0) {
      const b = -anim.blinkT / 0.14;
      lid = Math.abs(1 - 2 * Math.min(1, b));
      if (b >= 1) anim.blinkT = 2 + Math.random() * 3.5;
    }
    for (const e of eyes) e.scale.y = Math.max(0.08, lid);

    // the odd bill clap
    anim.clapT -= dt;
    if (anim.clapT < 0) {
      anim.clap += dt / 0.7;
      if (anim.clap >= 1) {
        anim.clap = 0;
        anim.clapT = 7 + Math.random() * 7;
      }
    }
    const open = anim.clap > 0 ? Math.sin(anim.clap * Math.PI * 2) ** 2 * 0.22 : 0;
    jaw.rotation.z = -open - 0.01;
    pouch.scale.y = 1 + Math.sin(t * 7.0) * 0.04 + compress * 0.08;

    // wings: held out for balance, constantly trimming, with an occasional flap
    anim.flapT -= dt;
    if (anim.flapT < 0 && anim.flap === 0) anim.flap = 0.0001;
    let flapLift = 0;
    if (anim.flap > 0) {
      anim.flap += dt / 1.1;
      const f = anim.flap;
      flapLift = Math.sin(f * Math.PI * 4) * Math.sin(f * Math.PI) * 0.75;
      if (f >= 1) {
        anim.flap = 0;
        anim.flapT = 5 + Math.random() * 6;
      }
    }
    for (const w of wings) {
      const s = w.side;
      const trim =
        Math.sin(t * 2.1 + s * 1.3) * 0.08 + Math.sin(t * 5.3 + s * 0.7) * 0.035 + Math.sin(t * 0.7 + s) * 0.06;
      // raise the wing on the outside of the turn
      const raise = 0.28 + trim + flapLift - s * lean * 0.45 + compress * 0.12;
      w.shoulder.rotation.x = -s * raise;
      w.shoulder.rotation.y = -s * (0.18 + 0.05 * Math.sin(t * 1.3 + s));
      w.shoulder.rotation.z = 0.12 + 0.06 * Math.sin(t * 2.1 + s * 1.3 + 0.6) - flapLift * 0.2;
      // wrist bends against the flap so the hand trails
      w.wrist.rotation.x = s * (0.12 + flapLift * 0.35 + trim * 0.4);
      w.wrist.rotation.y = -s * (0.32 + 0.06 * Math.sin(t * 1.9 + s));
      const spread = 1 + 0.15 * Math.sin(t * 3.1 + s) - flapLift * 0.2;
      for (const p of w.primaries) {
        p.pivot.rotation.y = -s * (Math.PI / 2) + s * p.baseAng * spread;
        p.pivot.rotation.z = flapLift * 0.15 * s;
      }
    }

    solveLegs();
  }

  return { group: root, update, hips, head };
}

import * as THREE from "three";
import { SUN_DIR, palette } from "./sky.js";

// CPU-simulated spray: rail spray from the board, offshore wind blowing mist
// off the lip, and churning whitewater mist on the broken section.
export function createSpray(max = 5000) {
  const pos = new Float32Array(max * 3);
  const vel = new Float32Array(max * 3);
  const life = new Float32Array(max);
  const maxLife = new Float32Array(max).fill(1);
  const size = new Float32Array(max);
  const alpha = new Float32Array(max);
  const drag = new Float32Array(max);
  const grav = new Float32Array(max);
  const airX = new Float32Array(max);
  const airZ = new Float32Array(max);
  const baseAlpha = new Float32Array(max);
  let cursor = 0;

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute("aSize", new THREE.BufferAttribute(size, 1).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute("aAlpha", new THREE.BufferAttribute(alpha, 1).setUsage(THREE.DynamicDrawUsage));

  const material = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    uniforms: {
      uScale: { value: 500 },
      uSunDir: { value: SUN_DIR },
      uSunColor: { value: palette.sun },
    },
    vertexShader: /* glsl */ `
      attribute float aSize;
      attribute float aAlpha;
      uniform float uScale;
      uniform vec3 uSunDir;
      varying float vAlpha;
      varying float vBack;
      void main() {
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mv;
        gl_PointSize = max(aSize * uScale / -mv.z, 0.0);
        vec3 world = (modelMatrix * vec4(position, 1.0)).xyz;
        vec3 V = normalize(world - cameraPosition);
        vBack = pow(max(dot(V, uSunDir), 0.0), 4.0);
        vAlpha = aAlpha;
      }`,
    fragmentShader: /* glsl */ `
      uniform vec3 uSunColor;
      varying float vAlpha;
      varying float vBack;
      void main() {
        vec2 c = gl_PointCoord - 0.5;
        float r = length(c);
        float a = smoothstep(0.5, 0.0, r);
        a *= a;
        if (a * vAlpha < 0.003) discard;
        vec3 col = vec3(0.86, 0.92, 0.95) + uSunColor * vBack * 1.8;
        gl_FragColor = vec4(col, a * vAlpha);
      }`,
  });

  const points = new THREE.Points(geo, material);
  points.frustumCulled = false;

  function spawn(x, y, z, vx, vy, vz, o) {
    const i = cursor;
    cursor = (cursor + 1) % max;
    pos[i * 3] = x;
    pos[i * 3 + 1] = y;
    pos[i * 3 + 2] = z;
    vel[i * 3] = vx;
    vel[i * 3 + 1] = vy;
    vel[i * 3 + 2] = vz;
    life[i] = 0;
    maxLife[i] = o.life;
    size[i] = o.size;
    baseAlpha[i] = o.alpha;
    drag[i] = o.drag;
    grav[i] = o.gravity;
    airX[i] = o.airX;
    airZ[i] = o.airZ;
  }

  function update(dt) {
    for (let i = 0; i < max; i++) {
      if (life[i] >= maxLife[i]) {
        alpha[i] = 0;
        continue;
      }
      life[i] += dt;
      const k = life[i] / maxLife[i];
      const d = Math.min(1, drag[i] * dt);
      const j = i * 3;
      vel[j] += (airX[i] - vel[j]) * d;
      vel[j + 1] += -grav[i] * dt - vel[j + 1] * d * 0.3;
      vel[j + 2] += (airZ[i] - vel[j + 2]) * d;
      pos[j] += vel[j] * dt;
      pos[j + 1] += vel[j + 1] * dt;
      pos[j + 2] += vel[j + 2] * dt;
      // fade in quickly, out slowly; mist grows as it disperses
      alpha[i] = baseAlpha[i] * Math.min(1, k * 8) * (1 - k) * (1 - k * 0.3);
      size[i] *= 1 + dt * 0.6;
    }
    geo.attributes.position.needsUpdate = true;
    geo.attributes.aSize.needsUpdate = true;
    geo.attributes.aAlpha.needsUpdate = true;
  }

  return { points, spawn, update, material };
}

import * as THREE from "three";
import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/examples/jsm/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/examples/jsm/postprocessing/OutputPass.js";
import { createSky, SUN_DIR, palette } from "./sky.js";
import { createOcean, heightAt, normalAt, VX, TRAIL_COUNT } from "./ocean.js";
import { createBoard } from "./board.js";
import { createPelican } from "./pelican.js";
import { createSpray } from "./spray.js";

// ---------- renderer / scene ----------
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.75));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(42, window.innerWidth / window.innerHeight, 0.05, 4000);

const sky = createSky();
scene.add(sky.group);

const ocean = createOcean();
scene.add(ocean.mesh);

// ---------- rider ----------
const rider = new THREE.Group();
scene.add(rider);
const board = createBoard();
rider.add(board.group);
const pelican = createPelican();
pelican.group.position.set(-0.05, board.deckHeight(-0.05) + 0.006, 0);
rider.add(pelican.group);

const spray = createSpray(5000);
scene.add(spray.points);

// ---------- lights ----------
const hemi = new THREE.HemisphereLight("#a9c8ff", "#2b7b80", 1.15);
scene.add(hemi);
const sun = new THREE.DirectionalLight(palette.sun, 2.7);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -2.2;
sun.shadow.camera.right = 2.2;
sun.shadow.camera.top = 2.2;
sun.shadow.camera.bottom = -2.2;
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 40;
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.015;
scene.add(sun, sun.target);
const fill = new THREE.DirectionalLight("#ffe0bf", 0.75);
scene.add(fill, fill.target);

// ---------- distant pelicans gliding in a line ----------
const flock = new THREE.Group();
scene.add(flock);
const birdMat = new THREE.MeshBasicMaterial({ color: new THREE.Color("#4a4f5c") });
const birds = [];
for (let i = 0; i < 4; i++) {
  const b = new THREE.Group();
  const body = new THREE.Mesh(new THREE.SphereGeometry(1, 10, 8), birdMat);
  body.scale.set(0.9, 0.22, 0.22);
  b.add(body);
  const beak = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.9, 6), birdMat);
  beak.rotation.z = -Math.PI / 2;
  beak.position.set(1.2, 0.05, 0);
  b.add(beak);
  const wings = [1, -1].map((s) => {
    const w = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.04, 1.9), birdMat);
    w.geometry.translate(0, 0, 0.95 * s);
    b.add(w);
    return { w, s };
  });
  b.position.set(-i * 3.2, i * 0.15, -i * 1.6);
  flock.add(b);
  birds.push({ b, wings, phase: i * 0.45 });
}

// ---------- board motion along the wave face ----------
function boardPath(t) {
  return [
    2.6 * Math.sin(0.27 * t) + 0.9 * Math.sin(0.61 * t + 1.0),
    6.0 + 2.1 * Math.sin(0.62 * t) + 0.55 * Math.sin(1.37 * t + 2.0),
  ];
}

const trail = [];
for (let i = 0; i < TRAIL_COUNT; i++) trail.push({ x: 0, z: 0, age: 99 });
let trailCursor = 0;
let trailTimer = 0;
const TRAIL_LIFE = 2.6;

const tmp = {
  n: new THREE.Vector3(),
  f: new THREE.Vector3(),
  side: new THREE.Vector3(),
  up: new THREE.Vector3(),
  m: new THREE.Matrix4(),
  q: new THREE.Quaternion(),
  camLocal: new THREE.Vector3(),
};
let prevHeading = null;
let turnRate = 0;
let lean = 0;
let compress = 0;
const camTarget = new THREE.Vector3(0, 1.5, 6);
const camPos = new THREE.Vector3(5, 3, 14);
let first = true;

function rand(a, b) {
  return a + Math.random() * (b - a);
}

function updateRider(t, dt) {
  const [x, zRaw] = boardPath(t);
  const z = Math.max(3.7, zRaw);
  const h = 0.02;
  const [x1, z1] = boardPath(t + h);
  const [x0, z0] = boardPath(t - h);
  const hx = VX + (x1 - x0) / (2 * h);
  const hz = (Math.max(3.7, z1) - Math.max(3.7, z0)) / (2 * h);
  const speed = Math.hypot(hx, hz);
  const heading = Math.atan2(hz, hx);
  if (prevHeading !== null && dt > 0) {
    const raw = (heading - prevHeading) / dt;
    turnRate += (raw - turnRate) * Math.min(1, dt * 6);
  }
  prevHeading = heading;
  const targetLean = THREE.MathUtils.clamp(speed * turnRate * 0.16, -1, 1);
  lean += (targetLean - lean) * Math.min(1, dt * 4);

  // compression: going down the face (toward +z) loads the legs at the bottom turn
  const accel = (boardPath(t + h)[1] - 2 * zRaw + boardPath(t - h)[1]) / (h * h);
  const targetCompress = THREE.MathUtils.clamp(-accel * 0.25 + Math.abs(lean) * 0.4, 0, 1);
  compress += (targetCompress - compress) * Math.min(1, dt * 3);

  const n = normalAt(x, z, tmp.n);
  const f = tmp.f.set(hx, 0, hz).normalize();
  f.addScaledVector(n, -f.dot(n)).normalize();
  const side = tmp.side.crossVectors(f, n).normalize();
  const up = tmp.up.copy(n).addScaledVector(side, lean * 0.3).normalize();
  side.crossVectors(f, up).normalize();
  f.crossVectors(up, side).normalize();
  tmp.m.makeBasis(f, up, side);
  tmp.q.setFromRotationMatrix(tmp.m);
  if (first) rider.quaternion.copy(tmp.q);
  else rider.quaternion.slerp(tmp.q, Math.min(1, dt * 10));
  const y = heightAt(x, z);
  rider.position.set(x, y + 0.035, z);

  // foam trail left by the tail
  trailTimer += dt;
  if (trailTimer > 0.045) {
    trailTimer = 0;
    const p = trail[trailCursor];
    p.x = x - f.x * 0.95;
    p.z = z - f.z * 0.95;
    p.age = 0;
    trailCursor = (trailCursor + 1) % TRAIL_COUNT;
  }
  for (let i = 0; i < TRAIL_COUNT; i++) {
    const p = trail[i];
    p.age += dt;
    p.x -= VX * dt;
    p.z -= 0.9 * dt;
    const k = Math.min(1, p.age / TRAIL_LIFE);
    const r = 0.2 + p.age * 0.22;
    ocean.trail[i].set(p.x, p.z, Math.pow(1 - k, 1.6) * 0.75, 1 / (r * r));
  }
  ocean.uniforms.uBoard.value.copy(rider.position);

  // rail spray, heavier in hard turns
  const outward = lean >= 0 ? -1 : 1;
  const rate = 50 + 900 * Math.abs(lean) ** 1.5;
  const count = Math.floor(rate * dt + Math.random());
  for (let i = 0; i < count; i++) {
    const back = rand(0.4, 1.0);
    const px = x - f.x * back + side.x * outward * 0.26;
    const pz = z - f.z * back + side.z * outward * 0.26;
    const s = rand(1.2, 3.6) * (0.5 + Math.abs(lean));
    spray.spawn(
      px,
      y + 0.02,
      pz,
      side.x * outward * s - f.x * rand(0.5, 2) + up.x * rand(1, 3.5),
      up.y * rand(1.2, 3.8) * (0.6 + Math.abs(lean)),
      side.z * outward * s - f.z * rand(0.5, 2) + up.z * rand(1, 3.5),
      { life: rand(0.5, 1.1), size: rand(0.05, 0.16), alpha: 0.85, drag: 0.6, gravity: 9.8, airX: -VX, airZ: -2 }
    );
  }

  pelican.group.updateMatrixWorld();
  tmp.camLocal.copy(camera.position);
  pelican.group.worldToLocal(tmp.camLocal);
  pelican.update({ t, dt, lean, compress, camLocal: tmp.camLocal });
}

function updateWaveSpray(dt) {
  // offshore wind feathers mist off the lip
  let count = Math.floor(320 * dt + Math.random());
  for (let i = 0; i < count; i++) {
    const x = rand(-9, 40);
    const top = heightAt(x, 0) + 0.25;
    spray.spawn(x, top + rand(-0.1, 0.25), rand(1.7, 2.4), rand(-0.3, 0.3), rand(0.8, 2.6), rand(-1.5, -4.5), {
      life: rand(1.2, 2.4),
      size: rand(0.25, 0.6),
      alpha: 0.28,
      drag: 0.8,
      gravity: 2.2,
      airX: -VX,
      airZ: -6,
    });
  }
  // whitewater mist rolling off the broken section
  count = Math.floor(160 * dt + Math.random());
  for (let i = 0; i < count; i++) {
    const x = rand(-40, -9);
    const z = rand(-1, 7);
    spray.spawn(x, heightAt(x, z) + rand(0.1, 0.6), z, rand(-0.5, 0.5), rand(0.4, 1.2), rand(0.2, 1.4), {
      life: rand(2, 3.5),
      size: rand(0.8, 1.8),
      alpha: 0.17,
      drag: 0.5,
      gravity: 0.15,
      airX: -VX,
      airZ: 0.5,
    });
  }
  // chunky droplets tumbling down the broken face
  count = Math.floor(150 * dt + Math.random());
  for (let i = 0; i < count; i++) {
    const x = rand(-40, -8);
    spray.spawn(x, heightAt(x, 0) + rand(0.0, 0.4), rand(0.8, 1.8), rand(-0.4, 0.4), rand(1.5, 3.5), rand(1.5, 3.5), {
      life: rand(0.8, 1.4),
      size: rand(0.12, 0.3),
      alpha: 0.6,
      drag: 0.3,
      gravity: 9.8,
      airX: -VX,
      airZ: 0,
    });
  }
}

function updateCamera(t, dt) {
  const target = tmp.up.copy(rider.position).add(new THREE.Vector3(0.6, 0.7, 0));
  const k = first ? 1 : 1 - Math.exp(-dt * 2.5);
  camTarget.lerp(target, k);
  const az = 0.5 + 0.6 * Math.sin(t * 0.05) + 0.15 * Math.sin(t * 0.13 + 1.0);
  const dist = 6.2 + 1.6 * Math.sin(t * 0.043 + 1.0);
  const elev = 0.16 + 0.08 * Math.sin(t * 0.07 + 2.0);
  const desired = new THREE.Vector3(
    camTarget.x + Math.sin(az) * Math.cos(elev) * dist,
    camTarget.y + Math.sin(elev) * dist,
    camTarget.z + Math.cos(az) * Math.cos(elev) * dist
  );
  desired.y = Math.max(desired.y, heightAt(desired.x, desired.z) + 0.7);
  camPos.lerp(desired, first ? 1 : 1 - Math.exp(-dt * 1.5));
  camera.position.copy(camPos);
  // a touch of handheld drift
  camera.position.x += Math.sin(t * 1.3) * 0.03;
  camera.position.y += Math.sin(t * 1.7 + 1) * 0.03;
  camera.lookAt(camTarget);
}

function updateLights() {
  sun.target.position.copy(rider.position);
  sun.position.copy(rider.position).addScaledVector(SUN_DIR, 20);
  fill.target.position.copy(rider.position);
  fill.position.copy(camera.position).add(new THREE.Vector3(0, 2, 0));
}

function updateFlock(t, dt) {
  const span = 260;
  const fx = ((t * 3.5) % span) - span / 2;
  flock.position.set(fx, 5.5 + Math.sin(t * 0.3) * 0.6, -95);
  for (const bd of birds) {
    const cycle = (t * 0.35 + bd.phase) % 1;
    const flapping = cycle < 0.35;
    const ang = flapping ? Math.sin(t * 7 + bd.phase * 5) * 0.45 : 0.06;
    for (const { w, s } of bd.wings) w.rotation.x = -s * ang;
    bd.b.position.y = bd.b.position.y * 0.98 + (Math.sin(t * 0.8 + bd.phase * 3) * 0.3) * 0.02;
  }
}

// ---------- post ----------
const rt = new THREE.WebGLRenderTarget(1, 1, { type: THREE.HalfFloatType, samples: 4 });
const composer = new EffectComposer(renderer, rt);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(1, 1), 0.32, 0.55, 0.92);
composer.addPass(bloom);
composer.addPass(new OutputPass());

function resize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  composer.setPixelRatio(renderer.getPixelRatio());
  composer.setSize(w, h);
  const px = h * renderer.getPixelRatio();
  spray.material.uniforms.uScale.value = (px * 0.5) / Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
}
window.addEventListener("resize", resize);
resize();

// ---------- loop ----------
const clock = new THREE.Clock();
let t = 3;
function frame() {
  const dt = Math.min(clock.getDelta(), 1 / 20);
  t += dt;
  ocean.update(t);
  updateRider(t, dt);
  updateWaveSpray(dt);
  spray.update(dt);
  updateCamera(t, dt);
  updateLights();
  updateFlock(t, dt);
  sky.update(camera);
  first = false;
  composer.render(dt);
  requestAnimationFrame(frame);
}
// warm the spray up so the first frame isn't empty
for (let i = 0; i < 90; i++) {
  ocean.update(t);
  updateRider(t, 1 / 30);
  updateWaveSpray(1 / 30);
  spray.update(1 / 30);
  t += 1 / 30;
  first = false;
}
first = true;
requestAnimationFrame(frame);

